<script setup lang="ts">
import AppIcon from '../AppIcon.vue'
import {onMounted,onBeforeUnmount,ref,watch} from 'vue'
import {ElMessageBox} from 'element-plus'
import {listMaterials,deleteMaterial,retryMaterial,type Material} from '../../api/materials'
import {pptMaterialApi} from '../../api/presentations'
import {errorText} from '../../api/http'
const props=defineProps<{projectId?:string;pendingFiles?:File[];saving?:boolean;refreshToken?:number;compact?:boolean;kind?:"ppt"|"video";projectRevision?:number}>()
const emit=defineEmits<{changed:[];pendingChange:[files:File[]]}>()
const items=ref<Material[]>([]),localPending=ref<File[]>(props.pendingFiles??[]),busy=ref(false),error=ref('')
let timer:ReturnType<typeof setTimeout>|undefined,disposed=false
const labels:Record<string,string>={stored:'已保存，生成时解析',pending:'等待解析',parsing:'正在解析',ready:'解析完成',failed:'解析失败'}
async function load(){if(!props.projectId||disposed)return;try{items.value=await (props.kind==='ppt'?pptMaterialApi.list(props.projectId):listMaterials(props.projectId));if(!Array.isArray(items.value))items.value=[]}catch(e){error.value=errorText(e)}finally{schedule()}}
function schedule(){clearTimeout(timer);if(!disposed&&items.value.some(m=>['pending','parsing'].includes(m.status))&&!document.hidden)timer=setTimeout(load,2000)}
async function choose(event:Event){const input=event.target as HTMLInputElement;const files=Array.from(input.files??[]);error.value='';const valid=[];for(const file of files){if(file.size>25*1024*1024){error.value='单个文件不能超过 25 MiB';continue}valid.push(file)}if(valid.length){localPending.value=[...localPending.value,...valid];emit('pendingChange',localPending.value)}input.value=''}
watch(()=>props.pendingFiles,(files)=>{localPending.value=files??[]},{deep:true})
async function remove(m:Material){try{await ElMessageBox.confirm('确定删除素材“'+m.filename+'”？','删除素材',{type:'warning'});busy.value=true;await (props.kind==='ppt'?pptMaterialApi.remove(props.projectId!,m.id,props.projectRevision!):deleteMaterial(props.projectId!,m.id));emit('changed');await load()}catch(e){if(e!=='cancel'&&e!=='close')error.value=errorText(e)}finally{busy.value=false}}
async function retry(m:Material){busy.value=true;try{await (props.kind==='ppt'?pptMaterialApi.retry(props.projectId!,m.id,props.projectRevision!):retryMaterial(props.projectId!,m.id));await load()}catch(e){error.value=errorText(e)}finally{busy.value=false}}
function visibility(){if(!document.hidden)void load();else clearTimeout(timer)}
watch(()=>[props.projectId,props.refreshToken],()=>{void load()})
onMounted(()=>{void load();document.addEventListener('visibilitychange',visibility)})
onBeforeUnmount(()=>{disposed=true;clearTimeout(timer);document.removeEventListener('visibilitychange',visibility)})
</script>
<template><section class="materials" :class="{'materials--compact':compact}" aria-label="参考素材"><div class="upload-heading"><label class="file-button" :class="{disabled:busy||saving}"><AppIcon name="attach"/><span>参考素材</span><input type="file" multiple accept=".ppt,.pptx,.pdf,.doc,.docx,.png,.jpg,.jpeg,.webp" :disabled="busy||saving" aria-label="上传参考素材" @change="choose"/></label><template v-if="compact"><span class="upload-hint">保存草稿时上传，生成大纲时解析</span><el-popover placement="bottom-start" :width=300 trigger="click"><template #reference><button type="button" class="material-help" aria-label="查看素材上传说明"><AppIcon name="info"/></button></template><p>支持 PPT/PPTX、PDF、Word、PNG/JPEG/WebP。单文件 25 MiB，每项目最多 10 个文件、累计 100 MiB。选择文件后点击“保存草稿”上传到 MinIO，点击“生成大纲”时自动保存并解析。</p><p>可以先选择素材，未保存前不会上传。</p></el-popover></template></div><template v-if="!compact"><p class="ev-muted">支持 PPT/PPTX、PDF、Word、PNG/JPEG/WebP。单文件 25 MiB，每项目最多 10 个文件、累计 100 MiB。选择文件后点击“保存草稿”上传到 MinIO，点击“生成大纲”时自动保存并解析。</p><p v-if="!localPending.length&&!projectId" class="ev-muted">可以先选择素材，未保存前不会上传。</p></template><p v-if="busy||saving" role="status">{{saving?'正在保存草稿并上传素材，请稍候…':'正在处理，请稍候…'}}</p><el-alert v-if="error" :title="error" type="error" :closable="false"/><ul v-if="items.length||localPending.length"><li v-for="file in localPending" :key="`pending-${file.name}-${file.size}-${file.lastModified}`"><div><strong>{{file.name}}</strong><small>{{(file.size/1024).toFixed(1)}} KiB · 点击保存草稿时上传</small></div><div class="material-actions"><el-button text type="danger" :disabled="busy||saving" @click="localPending=localPending.filter(item=>item!==file);emit('pendingChange',localPending)">移除</el-button></div></li><li v-for="m in items" :key="m.id"><div><a :href="(kind==='ppt'?'/api/presentations/':'/api/projects/')+projectId+'/materials/'+m.id+'/download'">{{m.filename}}</a><small>{{(m.size/1024).toFixed(1)}} KiB · {{labels[m.status]??m.status}}</small><p v-if="m.error_message" class="error">{{m.error_message}}</p><el-alert v-if="m.parse_warnings?.length" title="部分内容未解析" type="warning" :closable="false" show-icon><p v-for="(warning,index) in m.parse_warnings" :key="index">{{warning.location}}：{{warning.message}}</p></el-alert></div><div class="material-actions"><el-button v-if="m.status==='failed'" :disabled="busy||saving" @click="retry(m)">重试</el-button><el-button text type="danger" :disabled="busy||saving||['pending','parsing'].includes(m.status)" @click="remove(m)">删除</el-button></div></li></ul></section></template>
<style scoped>
.materials{padding:0;margin-bottom:12px}.upload-heading{display:flex;align-items:center;gap:12px}.file-button{position:relative;display:inline-flex;align-items:center;gap:7px;min-height:40px;padding:8px 10px;margin-left:-10px;border:1px solid transparent;border-radius:7px;cursor:pointer;color:var(--ev-color-primary-dark);font-size:12px;background:transparent}.file-button:hover{background:var(--ev-color-surface-muted)}.file-button .app-icon{width:18px;height:18px}.file-button input{position:absolute;inset:0;opacity:0;width:100%;height:100%;cursor:pointer}.file-button:focus-within{outline:2px solid var(--ev-color-primary);outline-offset:2px}.disabled{opacity:.55;cursor:not-allowed}p{font-size:11px;line-height:1.8;margin:4px 0 8px}ul{list-style:none;padding:0;margin:10px 0;display:grid;gap:8px}li{display:flex;justify-content:space-between;align-items:center;gap:14px;padding:10px 12px;border:1px solid var(--ev-color-border);border-radius:8px;background:var(--ev-color-surface-muted);font-size:12px}li>div{min-width:0}strong,a{overflow-wrap:anywhere}a{color:var(--ev-color-primary-dark)}small{display:block;color:var(--ev-color-muted);margin-top:4px;font-size:11px}.error{color:var(--ev-color-danger)}.material-actions{display:flex;align-items:center;flex-shrink:0}.material-actions .el-button{margin:0}@media(max-width:480px){li{flex-wrap:wrap;gap:4px}.materials>p{font-size:11px}}
.upload-hint{color:var(--ev-color-muted);font-size:11px;line-height:1.5}.material-help{display:grid;place-items:center;flex:none;width:32px;height:32px;border:0;border-radius:6px;background:transparent;color:var(--ev-color-muted);cursor:pointer}.material-help:hover{background:var(--ev-color-surface-muted);color:var(--ev-color-primary)}.material-help .app-icon{width:16px;height:16px}.materials--compact .upload-heading{gap:8px;flex-wrap:wrap}.materials--compact .file-button{min-height:32px;padding-top:4px;padding-bottom:4px}.materials--compact{margin-bottom:4px}@media(max-width:480px){.upload-hint{flex:1;min-width:120px;font-size:10px}.materials--compact .upload-heading{gap:4px}}
</style>
